window.publishedRecipes=Object.assign(window.publishedRecipes||{},{"61":{"name":"Jamaican Fried Dumplings","photo":"https://www.themealdb.com/images/media/meals/dd7t4d1764877271.jpg","url":"https://www.myforkinglife.com/jamaican-fried-dumplings/#recipe","source":"TheMealDB","originalId":"53356","items":[{"name":"All purpose flour","q":2.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Baking Powder","q":2.0,"u":"tsp","section":"Pantry","seasoning":false,"prep":""},{"name":"Salt","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Milk","q":3.0,"u":"/4 cup","section":"Dairy","seasoning":false,"prep":""},{"name":"Oil","q":1.5,"u":"cup","section":"Pantry","seasoning":true,"prep":""}],"steps":["Add flour, baking powder, and salt in a large bowl and stir to combine. Pour in the milk and stir until combined. Then roll the mixture into a ball and lightly knead until it comes together.","Break off about 10 pieces of dough and form them into balls. Set them aside.","In a 10-inch skillet, heat enough oil over medium heat to fry the dumplings, until the oil is about 350 degrees.","Once the dumplings are browned on one side, flip them and cook until both sides are browned, about 2-3 minutes each.","Once done, remove the dumplings from the oil and place them on paper towels or a cooling rack to drain off any excess oil.","Serve and enjoy."],"cat":"Vegetarian","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"62":{"name":"Air Fryer Egg Rolls","photo":"https://www.themealdb.com/images/media/meals/grhn401765687086.jpg","url":"https://www.simplyrecipes.com/recipes/air_fryer_chinese_egg_rolls/","source":"TheMealDB","originalId":"53373","items":[{"name":"Olive Oil","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Ground Pork","q":1.0,"u":"lb","section":"Meat","seasoning":false,"prep":""},{"name":"Garlic","q":1.0,"u":"clove peeled crushed","section":"Produce","seasoning":false,"prep":""},{"name":"Ginger","q":1.0,"u":"tablespoon","section":"Produce","seasoning":false,"prep":""},{"name":"Carrots","q":1.0,"u":"medium","section":"Produce","seasoning":false,"prep":""},{"name":"Scallions","q":3.0,"u":"chopped","section":"Pantry","seasoning":false,"prep":""},{"name":"Cabbage","q":3.0,"u":"Cups","section":"Produce","seasoning":false,"prep":""},{"name":"Soy Sauce","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Rice Vinegar","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Egg Roll Wrappers","q":12.0,"u":"","section":"Dairy","seasoning":false,"prep":""},{"name":"Oil","q":1,"u":"","literal":"For brushing","section":"Pantry","seasoning":true,"prep":""},{"name":"Duck Sauce","q":1,"u":"","literal":"To serve","section":"Pantry","seasoning":false,"prep":""},{"name":"Plum Sauce","q":1,"u":"","literal":"To serve","section":"Pantry","seasoning":false,"prep":""},{"name":"Soy Sauce","q":1,"u":"","literal":"To serve","section":"Pantry","seasoning":true,"prep":""}],"steps":["Alternative Pan Fry Method: If you don’t have access to an air fryer, you can make these egg rolls using a traditional pan fry method. Add enough oil to a medium skillet with high walls so the oil is about 1/2 inch up the side of the skillet. Heat oil on medium high heat until it reaches 350°F. Add egg rolls and fry for 3 to 4 minutes, flip, and fry for another 3 to 4 minutes until golden brown. Remove and let them drain and cool on a few paper towels.","Cook the filling:","In a large skillet over medium heat, add the olive oil along with the ground pork or chicken. Break apart the meat with a spatula or wooden spoon as it cooks. Cook until the meat is cooked through, 6 to 8 minutes.","Add garlic, ginger, carrot, scallions, and cabbage. Continue to cook until cabbage wilts down and is soft, another 3 to 4 minutes, stirring regularly. Season the filling with soy sauce and rice wine vinegar, and take off the heat to cool. (This filling can be made in advance.)","Assemble the egg rolls:","Place a single egg roll wrapper on a dry surface with one point of the square facing you (like a diamond). Place about 1/4 cup of the egg roll filling mixture in the middle of the wrapper.","Dip your fingers in water and run around the edges of the wrapper. Then fold the edges of the wrapper over the center and start rolling the egg roll away from you to form a tight cylinder. Place on a plate and repeat until you are out of filling. You should get at least a dozen egg rolls.","Air fry the egg rolls:","Place the egg rolls in the basket of your air fryer. Spray or brush them lightly with oil. Add as many as you can without stacking the egg rolls, making sure they don’t touch. Air needs to circulate around them. Brush the egg rolls lightly with oil.","Place the basket in the air fryer and turn the air fryer to 350°F. Cook for 6 to 7 minutes, then flip the egg rolls, spray or brush with oil a second time on the bottom side, and cook for another 4 to 5 minutes.","Finished egg rolls should be golden brown and crispy! Serve immediately."],"cat":"Vegetarian","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"63":{"name":"Black Beans Hotpot","photo":"https://www.themealdb.com/images/media/meals/81ahfr1784394567.jpg","url":"https://www.recipesfromcostarica.com/recipes","source":"TheMealDB","originalId":"53536","items":[{"name":"Black Beans","q":400.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Onion","q":1.0,"u":"large","section":"Produce","seasoning":false,"prep":""},{"name":"Green Pepper","q":1.0,"u":"","section":"Produce","seasoning":true,"prep":""},{"name":"Red Pepper","q":1.0,"u":"","section":"Produce","seasoning":true,"prep":""},{"name":"Celery","q":1.0,"u":"/3 cup","section":"Produce","seasoning":false,"prep":""},{"name":"Garlic","q":4.0,"u":"Cloves Crushed","section":"Produce","seasoning":false,"prep":""},{"name":"Ground Cumin","q":1.5,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Oregano","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Salt","q":1.5,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Black Pepper","q":2.0,"u":"tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Water","q":5.0,"u":"Cups","section":"Pantry","seasoning":false,"prep":""}],"steps":["Add all the ingredients in the Instant pot, Lock the lid on and set the Instant Pot to High Pressure for 35 minutes.","Once the beans are done cooking, let the pressure release naturally for 20 minutes before releasing the remaining pressure.","Open and serve!","Let the beans get cool completely before saving them in the fridge or freezer."],"cat":"Vegetarian","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"64":{"name":"Air fryer patatas bravas","photo":"https://www.themealdb.com/images/media/meals/3m8yae1763257951.jpg","url":"https://www.bbcgoodfood.com/recipes/air-fryer-patatas-bravas","source":"TheMealDB","originalId":"53158","items":[{"name":"Potatoes","q":900.0,"u":"g","section":"Produce","seasoning":false,"prep":""},{"name":"Olive Oil","q":3.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Onion","q":1.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Garlic","q":1.0,"u":"clove peeled crushed","section":"Produce","seasoning":false,"prep":""},{"name":"Paprika","q":1.0,"u":"tblsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Tomato Puree","q":1.0,"u":"tblsp","section":"Produce","seasoning":false,"prep":""},{"name":"Tinned Tomatos","q":225.0,"u":"g","section":"Produce","seasoning":false,"prep":""},{"name":"Basil Leaves","q":1,"u":"","literal":"To serve","section":"Produce","seasoning":false,"prep":""}],"steps":["step 1","Soak the potatoes in just-boiled water for 30 mins, then drain and leave to air-dry for 5 mins. Heat the air fryer to 200C. Tip the potatoes into a bowl and drizzle over 1 tbsp of the oil and add 1/2 tsp each of salt and freshly ground black pepper. Mix to coat the potatoes all over, then tip into the air fryer basket and cook for 20-30 mins until crisp and golden.","step 2","Meanwhile, heat the remaining oil in a small pan over a medium-low heat and fry the onion for 8-10 mins until softened but not golden. Stir in the garlic and cook for a minute before adding the paprika and cooking for 30 seconds more. Stir in the tomato purée, cook for 1 min, then tip in the chopped tomatoes. Cook for 5-10 mins over a medium heat until thickened slightly.","step 3","Once the potatoes are cooked, tip out onto a platter and pour over the tomato sauce. Sprinkle with the basil leaves, then serve."],"cat":"Vegetarian","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline. The original placeholder has been replaced with a different real published recipe; the displayed name is the publisher's exact dish name."},"65":{"name":"Carrot and Bean Fritters","photo":"https://www.themealdb.com/images/media/meals/xjii2g1784836867.jpg","url":"https://estoniancuisine.com/2021/01/15/carrot-and-bean-fritters-porgandi-oakotletid/#more-12384","source":"TheMealDB","originalId":"53576","items":[{"name":"Carrots","q":400.0,"u":"g","section":"Produce","seasoning":false,"prep":""},{"name":"Canned Beans","q":200.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Garlic","q":4.0,"u":"cloves","section":"Produce","seasoning":false,"prep":""},{"name":"Flour","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":false,"prep":""},{"name":"Breadcrumbs","q":1.0,"u":"cup","section":"Bakery","seasoning":false,"prep":""},{"name":"Thyme","q":1,"u":"","literal":"Pinch","section":"Pantry","seasoning":true,"prep":""},{"name":"Parsley","q":1,"u":"","literal":"Pinch","section":"Produce","seasoning":false,"prep":""},{"name":"Salt","q":1,"u":"","literal":"Pinch","section":"Pantry","seasoning":true,"prep":""},{"name":"Pepper","q":1,"u":"","literal":"Pinch","section":"Produce","seasoning":true,"prep":""},{"name":"Thyme","q":1,"u":"","literal":"Pinch","section":"Pantry","seasoning":true,"prep":""},{"name":"Oil","q":1,"u":"","literal":"Splash","section":"Pantry","seasoning":true,"prep":""}],"steps":["Pour the beans into the sieve, remove liquid.","Grate carrots and add beans, Mix and mash together. Season with garlic, thyme, salt and pepper.","Form the dough into round buns, dip them slightly into the bread crumbs, and press the fritters.","Fry fritters in hot oil for a short time until the fritters are browned.  Place on the greased or /baking paper-lined oven plate and bake at 200C for 10 minutes."],"cat":"Vegetarian","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"66":{"name":"Arroz al horno (baked rice)","photo":"https://www.themealdb.com/images/media/meals/qt4i0n1763256454.jpg","url":"https://www.bbcgoodfood.com/recipes/arroz-al-horno-baked-rice","source":"TheMealDB","originalId":"53156","items":[{"name":"Extra Virgin Olive Oil","q":2.0,"u":"tbsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Pork belly slices","q":800.0,"u":"g","section":"Meat","seasoning":false,"prep":""},{"name":"Black Pudding","q":150.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Bacon lardon","q":100.0,"u":"g","section":"Meat","seasoning":false,"prep":""},{"name":"Onion","q":1.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Red Pepper","q":2.0,"u":"","section":"Produce","seasoning":true,"prep":""},{"name":"Plum Tomatoes","q":1.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Garlic Clove","q":8.0,"u":"","section":"Produce","seasoning":true,"prep":""},{"name":"Paprika","q":4.0,"u":"teaspoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Chilli Flakes","q":1.0,"u":"/2 teaspoon","section":"Produce","seasoning":false,"prep":""},{"name":"Dried white beans","q":200.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Chicken Stock","q":1.5,"u":"L","section":"Meat","seasoning":false,"prep":""},{"name":"Thyme","q":6.0,"u":"parts","section":"Pantry","seasoning":true,"prep":""},{"name":"Paella Rice","q":375.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Lemon Juice","q":1.0,"u":"","section":"Produce","seasoning":false,"prep":""}],"steps":["step 1","Heat oven to 200C/180C/gas 6. Heat half the oil in a deep frying or sauté pan (or shallow casserole dish) measuring around 30cm in diameter. Over a high heat, colour the pork belly slices on each side in several batches, then transfer to a bowl. Add the remaining oil to the pan and lower the heat to medium, then add the black pudding and bacon and fry all over for several mins. Remove with a slotted spoon. Fry the onion and peppers for around 10 mins until soft and pale gold, then add the tomato and cook until soft. Add the garlic, smoked paprika and chilli flakes and cook for another 2 mins, then put the pork, black pudding and bacon back in the pan. Add the beans, stock and whichever herb you're using, and bring everything to the boil.","step 2","Sprinkle the rice around the pork belly, pushing it underneath the stock. Let the stock come to the boil again, season well, then transfer to the oven (leave it uncovered). Cook for 20 mins without stirring, then check to see how the rice is doing. The rice should be tender and the stock absorbed. If it’s not ready, put back in the oven for another 5 mins, then check again. Taste for seasoning.","step 3","Squeeze lemon juice over the top and drizzle over some extra virgin olive oil just before serving, if you like."],"cat":"Rice & Bowls","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"67":{"name":"Noodle bowl salad","photo":"https://www.themealdb.com/images/media/meals/zry07j1763779321.jpg","url":"https://www.bbcgoodfood.com/recipes/noodle-bowl-salad","source":"TheMealDB","originalId":"53245","items":[{"name":"Rice Noodles","q":125.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Sugar Snap Peas","q":200.0,"u":"g","section":"Pantry","seasoning":true,"prep":""},{"name":"Sesame Seed Oil","q":2.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Spring Onions","q":4.0,"u":"sliced","section":"Produce","seasoning":false,"prep":""},{"name":"Coriander","q":1,"u":"","literal":"Handful","section":"Pantry","seasoning":false,"prep":""},{"name":"Hot Smoked Flaked Salmon","q":150.0,"u":"g","section":"Meat","seasoning":false,"prep":""},{"name":"Pretzels","q":1,"u":"","literal":"To serve","section":"Pantry","seasoning":false,"prep":""},{"name":"Soy Sauce","q":3.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Clear Honey","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Lemon Juice","q":1.0,"u":"tablespoon","section":"Produce","seasoning":false,"prep":""},{"name":"Ground Nut Oil","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Garlic","q":1.0,"u":"clove finely chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Ginger","q":1,"u":"","literal":"Knob","section":"Produce","seasoning":false,"prep":""}],"steps":["step 1","Drop the noodles into a large bowl, then pour over enough boiling water to cover. Tip in the sliced sugar snaps and leave for 4 minutes. Drain in a colander, put under cold running water to cool off, then drain again. Tip into a bowl and toss in the sesame oil.","step 2","Mix the dressing ingredients. Pile spring onions, coriander and salmon onto the noodles, pour over the dressing and toss everything together. Serve with a pretzel or bread roll."],"cat":"Rice & Bowls","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"68":{"name":"Jamaican Instant Pot Rice and Beans","photo":"https://www.themealdb.com/images/media/meals/11bvtm1764795135.jpg","url":"https://www.myforkinglife.com/jamaican-instant-pot-rice-and-beans/#recipe","source":"TheMealDB","originalId":"53352","items":[{"name":"Olive Oil","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Onion","q":1.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Garlic","q":1.0,"u":"clove finely chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Spring Onions","q":2.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Rice","q":2.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Coconut Milk","q":3.0,"u":"/4 cup","section":"Dairy","seasoning":false,"prep":""},{"name":"Water","q":3.0,"u":"/4 cup","section":"Pantry","seasoning":false,"prep":""},{"name":"Salt","q":1.5,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Allspice","q":1.0,"u":"/2 tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Black Pepper","q":1.0,"u":"/4 tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Kidney Beans","q":450.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Thyme","q":2.0,"u":"sprigs","section":"Pantry","seasoning":true,"prep":""}],"steps":["Instructions","Set Instant Pot to \"Sauté.\" Once Hot, add olive oil. Then add yellow onion and stir until softened, about 3 minutes. Add garlic and green onions and stir for about 30 more seconds.","Press “Cancel” on the Instant Pot. Add rice, coconut milk, water, salt, allspice, and black pepper and stir.","Pour undrained kidney beans on top of the rice mixture. Do not stir. Lay sprigs of thyme on top. Cover the Instant Pot, ensuring the valve is set to “Sealing.”","Press “Manual” or “Pressure Cook” on the Instant Pot and set for High pressure for 6 minutes.","Once the pressure cooking time is done, allow it to natural release for 10 minutes, then quick release any remaining pressure by moving valve to \"Venting\"","Open lid and remove thyme sprigs. Fluff rice with fork and Enjoy!","Stove Top Instructions","Heat olive oil in a large pot over medium heat. Add yellow onion and stir until softened, about 3 minutes. Add garlic and green onions and stir for about 30 more seconds.","Add rice, undrained kidney beans, coconut milk, water, salt, allspice, and black pepper and stir until combined. Lay thyme on top. Bring mixture to a simmer.","Cover with a lid and reduce heat to low. Allow to cook for 18 minutes over low heat, then remove from heat. Leave the lid on for an additional 5 minutes.","Open the lid and remove the thyme. Fluff rice with fork. Enjoy."],"cat":"Vegetarian","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"69":{"name":"Bai Sach Chrouk – Grilled Pork with Rice","photo":"https://www.themealdb.com/images/media/meals/f0cdwk1782688162.jpg","url":"https://recipes-for-life.com/cambodian-recipes/","source":"TheMealDB","originalId":"53496","items":[{"name":"Pork Shoulder","q":650.0,"u":"g","section":"Meat","seasoning":false,"prep":""},{"name":"Coconut Milk","q":1.0,"u":"/4 cup","section":"Dairy","seasoning":false,"prep":""},{"name":"Soy Sauce","q":3.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Oyster Sauce","q":2.0,"u":"tablespoons","section":"Pantry","seasoning":false,"prep":""},{"name":"Honey","q":2.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Garlic","q":4.0,"u":"cloves","section":"Produce","seasoning":false,"prep":""},{"name":"Black Pepper","q":1.0,"u":"tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Jasmine Rice","q":2.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Water","q":4.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Vegetable Oil","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Cucumber","q":1.0,"u":"sliced","section":"Produce","seasoning":false,"prep":""},{"name":"Cilantro Leaves","q":1,"u":"","literal":"Garnish","section":"Produce","seasoning":false,"prep":""}],"steps":["1. In a large bowl, combine the coconut milk, soy sauce, oyster sauce, honey, minced garlic, and black pepper to make the marinade.","2. Add the thinly sliced pork shoulder to the marinade, ensuring each piece is fully coated, then cover and refrigerate for at least 30 minutes to allow the flavors to penetrate.","3. While the pork marinates, rinse the jasmine rice under cold water until the water runs clear to remove excess starch, which helps prevent clumping.","4. In a medium pot, combine the rinsed rice and 4 cups of water, bring to a boil over high heat, then reduce to a simmer, cover, and cook for 15 minutes until the water is absorbed and the rice is tender.","5. Heat a grill pan or outdoor grill to medium-high heat (about 400°F) and lightly brush with vegetable oil to prevent sticking.","6. Remove the pork from the marinade, shaking off any excess, and place it on the hot grill, cooking for 3-4 minutes per side until nicely charred and cooked through with an internal temperature of 145°F.","7. Tip: Avoid overcrowding the grill pan to ensure even browning and proper caramelization of the marinade.","8. Once the pork is grilled, let it rest for 5 minutes before slicing to retain its juices and tenderness.","9. Tip: If you prefer a saucier dish, simmer the leftover marinade in a small saucepan for 5 minutes until slightly thickened and drizzle it over the pork.","10. Fluff the cooked rice with a fork to separate the grains and serve it warm alongside the grilled pork slices.","11. Arrange the thinly sliced cucumber and fresh cilantro leaves on top as a refreshing garnish.","12. Tip: For an extra kick, serve with a side of pickled vegetables or a squeeze of lime juice to balance the rich, savory flavors."],"cat":"Rice & Bowls","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"70":{"name":"Chicken & chorizo rice pot","photo":"https://www.themealdb.com/images/media/meals/fk80jp1763280767.jpg","url":"https://www.bbcgoodfood.com/recipes/chicken-chorizo-rice-pot","source":"TheMealDB","originalId":"53161","items":[{"name":"Oil","q":1.0,"u":"tblsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Chicken","q":1.0,"u":"whole","section":"Meat","seasoning":false,"prep":""},{"name":"Onion","q":1.0,"u":"Large Chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Red Pepper","q":1.0,"u":"chopped","section":"Produce","seasoning":true,"prep":""},{"name":"Garlic","q":3.0,"u":"Cloves Crushed","section":"Produce","seasoning":false,"prep":""},{"name":"Chorizo","q":225.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Tomato Puree","q":1.0,"u":"tblsp","section":"Produce","seasoning":false,"prep":""},{"name":"Thyme","q":1.0,"u":"tablespoon chopped","section":"Pantry","seasoning":true,"prep":""},{"name":"White Wine","q":150.0,"u":"ml","section":"Pantry","seasoning":false,"prep":""},{"name":"Chicken Stock","q":800.0,"u":"ml","section":"Meat","seasoning":false,"prep":""},{"name":"Rice","q":400.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Parsley","q":2.0,"u":"tbs chopped","section":"Produce","seasoning":false,"prep":""}],"steps":["step 1","Heat the oil in a large flameproof casserole dish and brown the chicken pieces on all sides – you may have to do this in batches. Remove from the dish and put to one side.","step 2","Lower the heat, add the onion and pepper, and gently cook for 10 mins until softened. Add the garlic and chorizo, and cook for a further 2 mins until the chorizo has released some of its oils into the dish. Stir in the tomato purée and cook for 1 min more.","step 3","Return the chicken pieces to the dish along with the thyme, white wine and stock. Bring the liquid to a boil, cover the dish with a tight-fitting lid and lower the heat. Cook for 30 mins.","step 4","Tip in the rice and stir everything together. Cover, set over a low heat and cook for a further 15 mins, or until the rice is cooked and has absorbed most of the cooking liquid. Remove from the heat and leave the dish to sit for 10 mins to absorb any remaining liquid. Season to taste and scatter with parsley to serve."],"cat":"Chicken","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"71":{"name":"Beef Banh Mi Bowls with Sriracha Mayo, Carrot & Pickled Cucumber","photo":"https://www.themealdb.com/images/media/meals/z0ageb1583189517.jpg","url":"https://www.themealdb.com/meal/52997","source":"TheMealDB","originalId":"52997","items":[{"name":"Rice","q":1,"u":"","literal":"White","section":"Pantry","seasoning":false,"prep":""},{"name":"Onion","q":1.0,"u":"","section":"Produce","seasoning":false,"prep":""},{"name":"Lime","q":1.0,"u":"","section":"Produce","seasoning":false,"prep":""},{"name":"Garlic Clove","q":3.0,"u":"","section":"Produce","seasoning":true,"prep":""},{"name":"Cucumber","q":1.0,"u":"","section":"Produce","seasoning":false,"prep":""},{"name":"Carrots","q":3.0,"u":"oz","section":"Produce","seasoning":false,"prep":""},{"name":"Ground Beef","q":1.0,"u":"lb","section":"Meat","seasoning":false,"prep":""},{"name":"Soy Sauce","q":2.0,"u":"oz","section":"Pantry","seasoning":true,"prep":""}],"steps":["Add'l ingredients: mayonnaise, siracha","1","Place rice in a fine-mesh sieve and rinse until water runs clear. Add to a small pot with 1 cup water (2 cups for 4 servings) and a pinch of salt. Bring to a boil, then cover and reduce heat to low. Cook until rice is tender, 15 minutes. Keep covered off heat for at least 10 minutes or until ready to serve.","2","Meanwhile, wash and dry all produce. Peel and finely chop garlic. Zest and quarter lime (for 4 servings, zest 1 lime and quarter both). Trim and halve cucumber lengthwise; thinly slice crosswise into half-moons. Halve, peel, and medium dice onion. Trim, peel, and grate carrot.","3","In a medium bowl, combine cucumber, juice from half the lime, ¼ tsp sugar (½ tsp for 4 servings), and a pinch of salt. In a small bowl, combine mayonnaise, a pinch of garlic, a squeeze of lime juice, and as much sriracha as you’d like. Season with salt and pepper.","4","Heat a drizzle of oil in a large pan over medium-high heat. Add onion and cook, stirring, until softened, 4-5 minutes. Add beef, remaining garlic, and 2 tsp sugar (4 tsp for 4 servings). Cook, breaking up meat into pieces, until beef is browned and cooked through, 4-5 minutes. Stir in soy sauce. Turn off heat; taste and season with salt and pepper.","5","Fluff rice with a fork; stir in lime zest and 1 TBSP butter. Divide rice between bowls. Arrange beef, grated carrot, and pickled cucumber on top. Top with a squeeze of lime juice. Drizzle with sriracha mayo."],"cat":"Beef","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"72":{"name":"Amok Trey – Cambodian Fish Curry","photo":"https://www.themealdb.com/images/media/meals/diuub11782687570.jpg","url":"https://recipes-for-life.com/cambodian-recipes/","source":"TheMealDB","originalId":"53495","items":[{"name":"Fish fillet","q":1.0,"u":"lb","section":"Meat","seasoning":false,"prep":""},{"name":"Coconut Milk","q":1.0,"u":"Can","section":"Dairy","seasoning":false,"prep":""},{"name":"Red Curry Paste","q":2.0,"u":"tablespoons","section":"Pantry","seasoning":false,"prep":""},{"name":"Fish Sauce","q":1.0,"u":"tablespoon","section":"Meat","seasoning":false,"prep":""},{"name":"Brown Sugar","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Chicken Stock","q":1.0,"u":"cup","section":"Meat","seasoning":false,"prep":""},{"name":"Egg","q":1.0,"u":"","section":"Dairy","seasoning":false,"prep":""},{"name":"Kaffir Lime Leaves","q":2.0,"u":"","section":"Produce","seasoning":false,"prep":""},{"name":"Vegetable Oil","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Banana Leaves","q":1,"u":"","literal":"Handful","section":"Pantry","seasoning":false,"prep":""},{"name":"Cilantro","q":1,"u":"","literal":"Garnish","section":"Produce","seasoning":false,"prep":""},{"name":"Lime","q":1,"u":"","literal":"Garnish","section":"Produce","seasoning":false,"prep":""}],"steps":["1. In a medium bowl, combine the coconut milk, red curry paste, fish sauce, palm sugar, and broth, whisking until smooth—this ensures no lumps in the sauce.","2. Heat the vegetable oil in a large skillet over medium heat (about 350°F) for 30 seconds until shimmering.","3. Pour the coconut milk mixture into the skillet and bring it to a gentle simmer, stirring occasionally, which should take about 3-4 minutes.","4. Add the fish cubes and kaffir lime leaves to the skillet, submerging them fully in the sauce.","5. Reduce the heat to low, cover the skillet, and let it cook for 10 minutes until the fish is opaque and flakes easily with a fork—avoid overcooking to keep it tender.","6. Stir in the beaten egg slowly, cooking for 2 more minutes until the sauce thickens slightly, which adds a rich, custard-like texture.","7. While the curry simmers, prepare the banana leaves by briefly passing them over a gas flame for 10 seconds to make them pliable, or use parchment paper as a handy alternative.","8. Spoon the curry into the center of each banana leaf square, folding the edges to form a tight packet to trap steam.","9. Place the packets in a steamer basket over boiling water and steam for 10 minutes until heated through and fragrant.","10. Carefully unwrap the packets and garnish with fresh cilantro and lime wedges before serving"],"cat":"Rice & Bowls","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline. The original placeholder has been replaced with a different real published recipe; the displayed name is the publisher's exact dish name."},"73":{"name":"Bengali Chicken Curry with Potatoes","photo":"https://www.themealdb.com/images/media/meals/9ya6o71780262651.jpg","url":"https://www.allrecipes.com/recipe/215055/bengali-chicken-curry-with-potatoes/","source":"TheMealDB","originalId":"53453","items":[{"name":"Olive Oil","q":2.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Onion","q":2.0,"u":"diced","section":"Produce","seasoning":false,"prep":""},{"name":"Ginger Garlic Paste","q":1.0,"u":"tablespoon","section":"Produce","seasoning":false,"prep":""},{"name":"Tomato","q":2.0,"u":"diced","section":"Produce","seasoning":false,"prep":""},{"name":"Cayenne Pepper","q":1.0,"u":"tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Curry Powder","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Garam Masala","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Ground Turmeric","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Ground Cumin","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Chicken Breast","q":4.0,"u":"","section":"Meat","seasoning":false,"prep":""},{"name":"Red Potatoes","q":2.0,"u":"large","section":"Produce","seasoning":false,"prep":""},{"name":"Cilantro","q":1.0,"u":"/2 cup","section":"Produce","seasoning":false,"prep":""}],"steps":["Heat the olive oil in a large skillet over medium-high heat.","Cook and stir the onions in the hot oil until translucent, about 5 minutes.","Add the ginger-garlic paste and continue cooking another 5 minutes.","Reduce heat to medium; stir the tomatoes into the mixture and cook until the tomatoes are pulpy, 5 to 10 minutes.","Season with the cayenne pepper, curry powder, garam masala, turmeric, and cumin; cook and stir another 5 minutes.","Add the chicken and potatoes to the mixture in the skillet; simmer, stirring occasionally, until the potatoes are tender and the chicken is no longer pink in the center, about 20 minutes.","Sprinkle the cilantro over the mixture and continue simmering another 10 minutes.","Serve hot."],"cat":"Chicken","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"74":{"name":"Chicken Fried Rice","photo":"https://www.themealdb.com/images/media/meals/wuyd2h1765655837.jpg","url":"https://www.simplyrecipes.com/recipes/chicken_fried_rice/","source":"TheMealDB","originalId":"53367","items":[{"name":"Chicken Thighs","q":1.0,"u":"lb","section":"Meat","seasoning":false,"prep":""},{"name":"Salt","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Canola Oil","q":3.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Egg","q":3.0,"u":"Large","section":"Dairy","seasoning":false,"prep":""},{"name":"Onion","q":2.0,"u":"/3 Cup","section":"Produce","seasoning":false,"prep":""},{"name":"Garlic","q":2.0,"u":"cloves minced","section":"Produce","seasoning":false,"prep":""},{"name":"Ground Ginger","q":2.0,"u":"tsp","section":"Produce","seasoning":false,"prep":""},{"name":"Carrots","q":1.0,"u":"large","section":"Produce","seasoning":false,"prep":""},{"name":"Peas","q":2.0,"u":"/3 Cup","section":"Pantry","seasoning":false,"prep":""},{"name":"Jasmine Rice","q":4.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Scallions","q":2.0,"u":"sliced","section":"Pantry","seasoning":false,"prep":""},{"name":"Chinese five spice powder","q":1.0,"u":"/2 tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Soy Sauce","q":2.5,"u":"tbsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Sesame Seed Oil","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""}],"steps":["Fried rice is best made with leftover rice that's at least a day old. Otherwise it becomes gummy in the skillet.","If you don’t have any leftover rice from the night before, cook a batch of rice and spread it on a large baking sheet or several large plates. Let the rice dry out for about 1 to 2 hours before using it for fried rice.","Rice sticks to the pan very easily, so make sure to use a wok or pan that doesn’t have a sticky surface. I usually cook stir-fries in my seasoned carbon steel wok, but cast iron or nonstick pans work well, too. You might need to add a little more oil if things aren’t releasing easily.","Prepare the chicken:","Chop the chicken into small 1/4-inch to 1/2-inch cubes. Sprinkle 1/2 teaspoon of salt over the chicken and mix to combine. Set the chicken aside for about 10 minutes (I usually use this time to chop all the vegetables).","Scramble the egg:","Heat a wok or large sauté pan over medium-high heat. Swirl in a tablespoon of oil and add the whisked eggs. Use a spatula to quickly scramble the eggs, breaking the curds into smaller pieces as they come together. Transfer the eggs to a plate.","Cook the chicken:","Add another tablespoon of oil in the wok or pan. Add the chicken and cook for 4 to 5 minutes, stirring occasionally. Turn off the heat and transfer the cooked chicken to a plate.","Using your spatula, scrape off any chicken bits that are still stuck to the wok so they don't burn during the next step. You can also use paper towels to wipe down your wok or pan.","Cook the vegetables:","Swirl 1 tablespoon of oil into the wok over medium-high heat. Add the diced onions and cook them for 1 minute, until they start to soften. Mix in the minced garlic and ginger and cook until fragrant, about 30 seconds. Add the diced carrots and cook for 2 minutes, stirring frequently. Add 1/2 teaspoon salt and the peas, and stir to incorporate.","Cook the rice:","Add the rice to the wok or pan on top of the vegetables and stir to combine. Using the back of your spatula, smash any large chunks of rice to break them apart. Add the white and green parts of the sliced scallions (save the dark green parts) and five-spice powder. Stir to incorporate. If the rice starts to stick to the pan, stir in a little more oil.","Drizzle the soy sauce and sesame oil over the rice and stir to incorporate. Stir in the cooked chicken, scrambled eggs, and the dark parts of the scallions. Stir briefly to bring it together, and cook for another 1 to 2 minutes.","Serve:","Taste, and add more soy sauce if necessary. Serve immediately."],"cat":"Chicken","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"75":{"name":"Aubergine couscous salad","photo":"https://www.themealdb.com/images/media/meals/02s6gc1763799560.jpg","url":"https://www.bbcgoodfood.com/recipes/aubergine-couscous-salad","source":"TheMealDB","originalId":"53267","items":[{"name":"Aubergine","q":1.0,"u":"sliced","section":"Pantry","seasoning":false,"prep":""},{"name":"Olive Oil","q":3.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Couscous","q":140.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Vegetable Stock","q":225.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Cherry Tomatoes","q":200.0,"u":"g","section":"Produce","seasoning":false,"prep":""},{"name":"Mint","q":1,"u":"","literal":"Handful","section":"Pantry","seasoning":false,"prep":""},{"name":"Goats Cheese","q":100.0,"u":"g","section":"Dairy","seasoning":false,"prep":""},{"name":"Lemon","q":1,"u":"","literal":"Juice of 1/2","section":"Produce","seasoning":false,"prep":""}],"steps":["step 1","Heat grill to high. Put the aubergine on a baking sheet, brush with oil and season. Grill for about 15 mins, turning and brushing with more oil halfway, until browned and softened.","step 2","Meanwhile, tip the couscous into a large bowl, pour over the stock, then cover and leave for 10 mins. Mix the tomatoes, mint, goat’s cheese and remaining oil together. Fluff the couscous up with a fork, then stir in the aubergines, tomato mixture and lemon juice."],"cat":"Vegetarian","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline. The original placeholder has been replaced with a different real published recipe; the displayed name is the publisher's exact dish name."},"76":{"name":"Jamaican Rice and Peas","photo":"https://www.themealdb.com/images/media/meals/pkyvrn1764878267.jpg","url":"https://www.myforkinglife.com/jamaican-rice-and-peas/#recipe","source":"TheMealDB","originalId":"53357","items":[{"name":"Rice","q":2.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Coconut Milk","q":380.0,"u":"g","section":"Dairy","seasoning":false,"prep":""},{"name":"Kidney Beans","q":450.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Water","q":1.0,"u":"cup","section":"Pantry","seasoning":false,"prep":""},{"name":"Kosher Salt","q":2.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Ground Allspice","q":1.0,"u":"/2 tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Black Pepper","q":1.0,"u":"/4 tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Spring Onions","q":3.0,"u":"","section":"Produce","seasoning":false,"prep":""},{"name":"Thyme","q":2.0,"u":"sprigs","section":"Pantry","seasoning":true,"prep":""},{"name":"Scotch Bonnet","q":1.0,"u":"","section":"Pantry","seasoning":false,"prep":""}],"steps":["Equipment","Dutch oven","Add rice, coconut milk, kidney beans, water, kosher salt, allspice, and black pepper to a large pot and stir until combined. Lay green onions, thyme and Scotch bonnet pepper on top. Bring mixture to a boil.","Once boiling, reduce heat to low and cover with a lid. Allow to cook covered for 18 minutes over low heat, then remove from heat. Leave the lid on for an additional 5 minutes.","Open the lid and remove the green onion, Scotch bonnet pepper, and thyme. Fluff the rice and peas with a fork. Serve and enjoy."],"cat":"Vegetarian","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"77":{"name":"Thai fried rice with prawns & peas","photo":"https://www.themealdb.com/images/media/meals/hblwvg1763478203.jpg","url":"https://www.bbcgoodfood.com/recipes/thai-fried-rice-prawns-peas","source":"TheMealDB","originalId":"53198","items":[{"name":"Vegetable Oil","q":2.0,"u":"tbsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Red Onions","q":1.0,"u":"sliced","section":"Produce","seasoning":false,"prep":""},{"name":"Garlic Clove","q":2.0,"u":"sliced","section":"Produce","seasoning":true,"prep":""},{"name":"Red Chilli","q":1.0,"u":"sliced","section":"Produce","seasoning":false,"prep":""},{"name":"Raw King Prawns","q":250.0,"u":"g","section":"Meat","seasoning":false,"prep":""},{"name":"Brown Rice","q":140.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Frozen Peas","q":75.0,"u":"g","section":"Frozen","seasoning":false,"prep":""},{"name":"Soy Sauce","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Fish Sauce","q":1.0,"u":"tablespoon","section":"Meat","seasoning":false,"prep":""},{"name":"Coriander","q":1,"u":"","literal":"Bunch","section":"Pantry","seasoning":false,"prep":""},{"name":"Egg","q":4.0,"u":"large","section":"Dairy","seasoning":false,"prep":""},{"name":"Hotsauce","q":1,"u":"","literal":"To serve","section":"Pantry","seasoning":false,"prep":""}],"steps":["step 1","Heat 1 tbsp of the oil in a wok, add the onion, garlic and chilli, and cook for 2-3 mins until golden. Add the prawns and cook for 1 min. Tip in the rice and peas, and keep tossing until very hot. Add the soy and fish sauce, then stir through the chopped coriander. Keep warm while you fry the eggs.","step 2","Heat the remaining oil in a frying pan and fry the eggs with some seasoning. Divide the fried rice mix between 4 bowls and top each with a fried egg. Serve scattered with coriander, with chilli sauce, if you like."],"cat":"Rice & Bowls","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"78":{"name":"Jamaican Curry Chicken Recipe","photo":"https://www.themealdb.com/images/media/meals/o5fuq51764789643.jpg","url":"https://www.myforkinglife.com/jamaican-curry-chicken/","source":"TheMealDB","originalId":"53345","items":[{"name":"Chicken Thighs","q":2.0,"u":"Lbs","section":"Meat","seasoning":false,"prep":""},{"name":"Curry Powder","q":2.5,"u":"Tbs","section":"Pantry","seasoning":true,"prep":""},{"name":"All-purpose Seasoning","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Onion","q":1.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Spring Onions","q":3.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Green Pepper","q":1.0,"u":"/2","section":"Produce","seasoning":true,"prep":""},{"name":"Garlic","q":4.0,"u":"Cloves Chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Scotch Bonnet","q":1.0,"u":"chopped","section":"Pantry","seasoning":false,"prep":""},{"name":"Thyme","q":3.0,"u":"sprigs","section":"Pantry","seasoning":true,"prep":""},{"name":"Olive Oil","q":3.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Water","q":1.0,"u":"/4 cup","section":"Pantry","seasoning":false,"prep":""},{"name":"Russet Potato","q":1.0,"u":"large","section":"Produce","seasoning":false,"prep":""},{"name":"Salt","q":1,"u":"","literal":"To taste","section":"Pantry","seasoning":true,"prep":""},{"name":"Pepper","q":1,"u":"","literal":"To taste","section":"Produce","seasoning":true,"prep":""}],"steps":["Equipment","Dutch Oven","Instructions","Add chicken thighs, all-purpose seasoning, 1 tablespoon of curry powder, onion, green onions, green pepper, garlic cloves, scotch bonnet pepper (if using), and thyme to a large bowl and combine, making sure all chicken pieces are covered with the seasoning. Cover and refrigerate for at least 1 hour or up to overnight.","One the chicken is done marinating, remove onions, peppers, and garlic cloves from chicken and set aside.","Heat olive oil in a large heavy bottom pot over medium heat. Add remaining curry powder and stir, cooking for about 20-30 seconds. Add onions, green pepper, garlic cloves, thyme, and scotch bonnet pepper (if using) to pot and stir until onions have softened, about 3-5 minutes. If your onions and peppers are looking dry, add about 1 tablespoon of water.","Add chicken and ¼ cup of water to the pot. Cover and reduce heat to medium low. Cook, stirring occasionally, for 30-35 minutes.","When there is about 15 minutes remaining, stir in potato and continue to cook covered.","Once chicken is cooked and potatoes are softened, remove from heat. Salt and pepper to taste."],"cat":"Chicken","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"79":{"name":"Japanese gohan rice","photo":"https://www.themealdb.com/images/media/meals/kw92t41604181871.jpg","url":"https://www.bbcgoodfood.com/recipes/japanese-rice-gohan","source":"TheMealDB","originalId":"53033","items":[{"name":"Sushi Rice","q":300.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Mirin","q":1.0,"u":"tbs","section":"Pantry","seasoning":false,"prep":""},{"name":"Pickle Juice","q":1,"u":"","literal":"Garnish","section":"Pantry","seasoning":false,"prep":""},{"name":"Spring Onions","q":1,"u":"","literal":"Garnish","section":"Produce","seasoning":false,"prep":""}],"steps":["STEP 1","Rinsing and soaking your rice is key to achieving the perfect texture. Measure the rice into a bowl, cover with cold water, then use your fingers to massage the grains of rice – the water will become cloudy. Drain and rinse again with fresh water. Repeat five more times until the water stays clear.","STEP 2","Tip the rinsed rice into a saucepan with 400ml water, or 200ml dashi and 200ml water, bring to the boil, then turn down the heat to a low simmer, cover with a tight-fitting lid with a steam hole and cook for 15 mins. Remove from the heat and leave to sit for another 15 mins, then stir through the mirin. Remove the lid and give it a good stir. Serve with any or all of the optional toppings."],"cat":"Vegetarian","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"80":{"name":"Jerk chicken with rice & peas","photo":"https://www.themealdb.com/images/media/meals/tytyxu1515363282.jpg","url":"https://www.bbcgoodfood.com/recipes/2369635/jerk-chicken-with-rice-and-peas","source":"TheMealDB","originalId":"52937","items":[{"name":"Chicken Thighs","q":12.0,"u":"","section":"Meat","seasoning":false,"prep":""},{"name":"Lime","q":1.0,"u":"/2","section":"Produce","seasoning":false,"prep":""},{"name":"Spring Onions","q":1.0,"u":"bunch","section":"Produce","seasoning":false,"prep":""},{"name":"Ginger","q":1.0,"u":"tbs chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Garlic","q":3.0,"u":"cloves","section":"Produce","seasoning":false,"prep":""},{"name":"Onion","q":1.0,"u":"/2","section":"Produce","seasoning":false,"prep":""},{"name":"Red Chilli","q":3.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Thyme","q":1.0,"u":"/2 teaspoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Lime","q":1,"u":"","literal":"Juice of 1","section":"Produce","seasoning":false,"prep":""},{"name":"Soy Sauce","q":2.0,"u":"tbs","section":"Pantry","seasoning":true,"prep":""},{"name":"Vegetable Oil","q":2.0,"u":"tbs","section":"Pantry","seasoning":true,"prep":""},{"name":"Brown Sugar","q":3.0,"u":"tbs","section":"Pantry","seasoning":true,"prep":""},{"name":"Allspice","q":1.0,"u":"tbs","section":"Pantry","seasoning":true,"prep":""},{"name":"Basmati Rice","q":200.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Coconut Milk","q":400.0,"u":"g","section":"Dairy","seasoning":false,"prep":""},{"name":"Spring Onions","q":1.0,"u":"bunch","section":"Produce","seasoning":false,"prep":""},{"name":"Thyme","q":2.0,"u":"sprigs","section":"Pantry","seasoning":true,"prep":""},{"name":"Garlic","q":2.0,"u":"cloves chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Allspice","q":1.0,"u":"tbs","section":"Pantry","seasoning":true,"prep":""},{"name":"Kidney Beans","q":800.0,"u":"g","section":"Pantry","seasoning":false,"prep":""}],"steps":["To make the jerk marinade, combine all the ingredients in a food processor along with 1 tsp salt, and blend to a purée. If you’re having trouble getting it to blend, just keep turning off the blender, stirring the mixture, and trying again. Eventually it will start to blend up – don’t be tempted to add water, as you want a thick paste.","Taste the jerk mixture for seasoning – it should taste pretty salty, but not unpleasantly, puckering salty. You can now throw in more chillies if it’s not spicy enough for you. If it tastes too salty and sour, try adding in a bit more brown sugar until the mixture tastes well balanced.","Make a few slashes in the chicken thighs and pour the marinade over the meat, rubbing it into all the crevices. Cover and leave to marinate overnight in the fridge.","If you want to barbecue your chicken, get the coals burning 1 hr or so before you’re ready to cook. Authentic jerked meats are not exactly grilled as we think of grilling, but sort of smoke-grilled. To get a more authentic jerk experience, add some wood chips to your barbecue, and cook your chicken over slow, indirect heat for 30 mins. To cook in the oven, heat to 180C/160C fan/gas 4. Put the chicken pieces in a roasting tin with the lime halves and cook for 45 mins until tender and cooked through.","While the chicken is cooking, prepare the rice & peas. Rinse the rice in plenty of cold water, then tip it into a large saucepan with all the remaining ingredients except the kidney beans. Season with salt, add 300ml cold water and set over a high heat. Once the rice begins to boil, turn it down to a medium heat, cover and cook for 10 mins.","Add the beans to the rice, then cover with a lid. Leave off the heat for 5 mins until all the liquid is absorbed. Squeeze the roasted lime over the chicken and serve with the rice & peas, and some hot sauce if you like it really spicy."],"cat":"Chicken","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"81":{"name":"Chicken Shawarma with homemade garlic herb yoghurt sauce","photo":"https://www.themealdb.com/images/media/meals/hcg6l91763596970.jpg","url":"https://cookpad.com/eng/recipes/24343467?ref=search&search_term=saudi+arabia","source":"TheMealDB","originalId":"53218","items":[{"name":"Chicken Breast","q":1.0,"u":"kg","section":"Meat","seasoning":false,"prep":""},{"name":"Garlic","q":2.0,"u":"cloves minced","section":"Produce","seasoning":false,"prep":""},{"name":"Ground Coriander","q":1.0,"u":"tblsp","section":"Pantry","seasoning":false,"prep":""},{"name":"Ground Cumin","q":1.0,"u":"tblsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Ground Cardomom","q":1.0,"u":"tblsp","section":"Pantry","seasoning":false,"prep":""},{"name":"Cayenne Pepper","q":1.0,"u":"tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Smoked Paprika","q":2.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Salt","q":2.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Lemon Juice","q":2.0,"u":"tblsp","section":"Produce","seasoning":false,"prep":""},{"name":"Olive Oil","q":3.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Greek Yogurt","q":1.0,"u":"cup","section":"Dairy","seasoning":false,"prep":""},{"name":"Garlic","q":1.0,"u":"clove peeled crushed","section":"Produce","seasoning":false,"prep":""},{"name":"Cumin","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Lemon Juice","q":1,"u":"","literal":"Splash","section":"Produce","seasoning":false,"prep":""}],"steps":["1","Start by cutting your chicken up into reasonably small slices. Grab your ziplock bag and dump the freshly sliced chicken inside.","2","Add garlic, coriander, cumin, cardomom, cayenne pepper, paprika, salt, pepper, lemon juice and olive oil to the bag. Close the bag and mix thoroughly. Place in fridge for 10-12 hours (shorter is fine but longer is better).","3","Once ready to cook, heat your fry pan to medium-high and add a tiny bit of olive oil. Fry one side of all of your flatbreads until slightly toasty. Remove from pan, add enough oil to coat the fry pan. Put crumble fries into air fryer on 180 for 15 minutes shaking occasionally.","4","The pan should be pretty hot by now, add the chicken in 2 batches (unless you have a big fry pan) to avoid overcrowding. The chicken should get a nice sear and darker colour which is perfect. Cook for a further 5-8 minutes or until cooked through. Repeat with next chicken batch.","5","While chicken is cooking, place your Greek yoghurt into a bowl. Combine garlic, finely chopped mint and parsley, squeeze or so of lemon and cumin. Combine and add salt to taste. In a small bowl, combine 1tsp garlic powder, paprika, cumin, onion powder, oregano, dried parsley, cayenne pepper (optional) mix and leave aside for fries.","6","Season fries immediately once cooked and add salt to taste. Once the chicken is complete, serve immediately by laying out your flatbread, spreading the sauce evenly over the bread, add lettuce, onion, tomato, fries, chicken, feta and more sauce on top. Serve immediately."],"cat":"Chicken","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"82":{"name":"Brown Stew Chicken","photo":"https://www.themealdb.com/images/media/meals/sypxpx1515365095.jpg","url":"http://www.geniuskitchen.com/recipe/authentic-jamaican-brown-stew-chicken-347996","source":"TheMealDB","originalId":"52940","items":[{"name":"Chicken","q":1.0,"u":"whole","section":"Meat","seasoning":false,"prep":""},{"name":"Tomato","q":1.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Onions","q":2.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Garlic Clove","q":2.0,"u":"chopped","section":"Produce","seasoning":true,"prep":""},{"name":"Red Pepper","q":1.0,"u":"chopped","section":"Produce","seasoning":true,"prep":""},{"name":"Carrots","q":1.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Lime","q":1.0,"u":"","section":"Produce","seasoning":false,"prep":""},{"name":"Thyme","q":2.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Allspice","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Soy Sauce","q":2.0,"u":"tbs","section":"Pantry","seasoning":true,"prep":""},{"name":"Cornstarch","q":2.0,"u":"tsp","section":"Pantry","seasoning":false,"prep":""},{"name":"Coconut Milk","q":2.0,"u":"cups","section":"Dairy","seasoning":false,"prep":""},{"name":"Vegetable Oil","q":1.0,"u":"tbs","section":"Pantry","seasoning":true,"prep":""}],"steps":["Squeeze lime over chicken and rub well. Drain off excess lime juice.","Combine tomato, scallion, onion, garlic, pepper, thyme, pimento and soy sauce in a large bowl with the chicken pieces. Cover and marinate at least one hour.","Heat oil in a dutch pot or large saucepan. Shake off the seasonings as you remove each piece of chicken from the marinade. Reserve the marinade for sauce.","Lightly brown the chicken a few pieces at a time in very hot oil. Place browned chicken pieces on a plate to rest while you brown the remaining pieces.","Drain off excess oil and return the chicken to the pan. Pour the marinade over the chicken and add the carrots. Stir and cook over medium heat for 10 minutes.","Mix flour and coconut milk and add to stew, stirring constantly. Turn heat down to minimum and cook another 20 minutes or until tender."],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"83":{"name":"Crock Pot Chicken Baked Tacos","photo":"https://www.themealdb.com/images/media/meals/ypxvwv1505333929.jpg","url":"http://www.nobiggie.net/crock-pot-chicken-baked-tacos/","source":"TheMealDB","originalId":"52830","items":[{"name":"Chicken Breasts","q":4.0,"u":"- 6","section":"Meat","seasoning":false,"prep":""},{"name":"Vinaigrette Dressing","q":1.0,"u":"bottle","section":"Pantry","seasoning":false,"prep":""},{"name":"Cumin","q":1.5,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Smoked Paprika","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Garlic","q":1.0,"u":"teaspoon","section":"Produce","seasoning":false,"prep":""},{"name":"Refried Beans","q":1.0,"u":"can","section":"Pantry","seasoning":false,"prep":""},{"name":"Hard Taco Shells","q":12.0,"u":"","section":"Pantry","seasoning":false,"prep":""},{"name":"Shredded Mexican Cheese","q":2.0,"u":"cups","section":"Dairy","seasoning":false,"prep":""},{"name":"Grape Tomatoes","q":1,"u":"","literal":"Halved","section":"Produce","seasoning":false,"prep":""},{"name":"Jalapeno","q":1,"u":"","literal":"Sliced and Seeded","section":"Pantry","seasoning":false,"prep":""},{"name":"Avocado","q":1,"u":"","literal":"Peeled and Sliced","section":"Produce","seasoning":false,"prep":""},{"name":"Green Salsa","q":2.0,"u":"tablespoons","section":"Pantry","seasoning":false,"prep":""},{"name":"Sour Cream","q":3.0,"u":"tablespoons","section":"Dairy","seasoning":false,"prep":""},{"name":"Milk","q":1.0,"u":"tablespoon","section":"Dairy","seasoning":false,"prep":""}],"steps":["Put the uncooked chicken breasts in the crock pot. Pour the full bottle of salad dressing over the chicken. Sprinkle the rest of the ingredients over the top and mix them in a bit with a spoon.","Cover your crock pot with the lid and cook on high for 4 hours.","Remove all the chicken breasts from the crock pot and let cool.","Shred the chicken breasts and move to a glass bowl.","Pour most of the liquid over the shredded chicken.","FOR THE TACOS:","Make the guacamole sauce by mixing the avocado and green salsa together. Pour the guacamole mixture through a strainer until smooth and transfer to a squeeze bottle. Cut the tip off the lid of the squeeze bottle to make the opening more wide if needed.","Make the sour cream sauce by mixing the sour cream and milk together until you get a more liquid sour cream sauce. Transfer to a squeeze bottle.","In a 9x 13 glass baking dish, fill all 12+ tacos with a layer of refried beans, cooked chicken and shredded cheese.","Bake at 450 for 10-15 minutes just until the cheese is melted and bubbling.","Out of the oven top all the tacos with the sliced grape tomaotes, jalapeno and cilantro.","Finish with a drizzle of guacamole and sour cream.","Enjoy!"],"cat":"Chicken","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"84":{"name":"Beef Dumpling Stew","photo":"https://www.themealdb.com/images/media/meals/uyqrrv1511553350.jpg","url":"https://www.bbc.co.uk/food/recipes/beefstewwithdumpling_87333","source":"TheMealDB","originalId":"52873","items":[{"name":"Olive Oil","q":2.0,"u":"tbs","section":"Pantry","seasoning":true,"prep":""},{"name":"Butter","q":25.0,"u":"g","section":"Dairy","seasoning":false,"prep":""},{"name":"Beef","q":750.0,"u":"g","section":"Meat","seasoning":false,"prep":""},{"name":"Plain Flour","q":2.0,"u":"tblsp","section":"Pantry","seasoning":false,"prep":""},{"name":"Garlic","q":2.0,"u":"cloves minced","section":"Produce","seasoning":false,"prep":""},{"name":"Onions","q":175.0,"u":"g","section":"Produce","seasoning":false,"prep":""},{"name":"Celery","q":150.0,"u":"g","section":"Produce","seasoning":false,"prep":""},{"name":"Carrots","q":150.0,"u":"g","section":"Produce","seasoning":false,"prep":""},{"name":"Leek","q":2.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Swede","q":200.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Red Wine","q":150.0,"u":"ml","section":"Pantry","seasoning":false,"prep":""},{"name":"Beef Stock","q":500.0,"u":"g","section":"Meat","seasoning":false,"prep":""},{"name":"Bay Leaf","q":2.0,"u":"","section":"Pantry","seasoning":true,"prep":""},{"name":"Thyme","q":3.0,"u":"tbs","section":"Pantry","seasoning":true,"prep":""},{"name":"Parsley","q":3.0,"u":"tblsp chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Plain Flour","q":125.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Baking Powder","q":1.0,"u":"tsp","section":"Pantry","seasoning":false,"prep":""},{"name":"Suet","q":60.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Water","q":1,"u":"","literal":"Splash","section":"Pantry","seasoning":false,"prep":""}],"steps":["Preheat the oven to 180C/350F/Gas 4.","For the beef stew, heat the oil and butter in an ovenproof casserole and fry the beef until browned on all sides.","Sprinkle over the flour and cook for a further 2-3 minutes.","Add the garlic and all the vegetables and fry for 1-2 minutes.","Stir in the wine, stock and herbs, then add the Worcestershire sauce and balsamic vinegar, to taste. Season with salt and freshly ground black pepper.","Cover with a lid, transfer to the oven and cook for about two hours, or until the meat is tender.","For the dumplings, sift the flour, baking powder and salt into a bowl.","Add the suet and enough water to form a thick dough.","With floured hands, roll spoonfuls of the dough into small balls.","After two hours, remove the lid from the stew and place the balls on top of the stew. Cover, return to the oven and cook for a further 20 minutes, or until the dumplings have swollen and are tender. (If you prefer your dumplings with a golden top, leave the lid off when returning to the oven.)","To serve, place a spoonful of mashed potato onto each of four serving plates and top with the stew and dumplings. Sprinkle with chopped parsley."],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"85":{"name":"Beetroot Soup (Borscht)","photo":"https://www.themealdb.com/images/media/meals/zadvgb1699012544.jpg","url":"https://natashaskitchen.com/classic-russian-borscht-recipe/","source":"TheMealDB","originalId":"53078","items":[{"name":"Beetroot","q":3.0,"u":"","section":"Pantry","seasoning":false,"prep":""},{"name":"Olive Oil","q":4.0,"u":"tbs","section":"Pantry","seasoning":true,"prep":""},{"name":"Chicken Stock Cube","q":1.0,"u":"","section":"Meat","seasoning":false,"prep":""},{"name":"Water","q":6.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Potatoes","q":3.0,"u":"","section":"Produce","seasoning":false,"prep":""},{"name":"Cannellini Beans","q":1.0,"u":"can","section":"Pantry","seasoning":false,"prep":""},{"name":"Dill","q":1,"u":"","literal":"Garnish","section":"Pantry","seasoning":false,"prep":""}],"steps":["Chop the beetroot, add water and stock cube and cook for 15mins.","Add the other ingredients and boil until soft.","Finally add the beans and cook for 5mins.","Serve in the soup pot."],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"86":{"name":"Easy White Bean Soup","photo":"https://www.themealdb.com/images/media/meals/p5nzbk1782680889.jpg","url":"https://cookinglsl.com/bulgarian-white-bean-soup/","source":"TheMealDB","originalId":"53486","items":[{"name":"Cannellini Beans","q":1.0,"u":"lb","section":"Pantry","seasoning":false,"prep":""},{"name":"Onions","q":2.0,"u":"medium","section":"Produce","seasoning":false,"prep":""},{"name":"Vegetable Oil","q":2.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Red Pepper","q":2.0,"u":"medium","section":"Produce","seasoning":true,"prep":""},{"name":"Tomato Puree","q":1.0,"u":"/3 cup","section":"Produce","seasoning":false,"prep":""},{"name":"Carrots","q":2.0,"u":"medium","section":"Produce","seasoning":false,"prep":""},{"name":"Water","q":6.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Dried Mint","q":1.0,"u":"tsp","section":"Pantry","seasoning":false,"prep":""},{"name":"Thyme","q":1.0,"u":"/2 tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Summer Savoury","q":1.0,"u":"tsp","section":"Pantry","seasoning":false,"prep":""},{"name":"Black Pepper","q":1.0,"u":"tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Salt","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Parsley","q":1,"u":"","literal":"Garnish","section":"Produce","seasoning":false,"prep":""}],"steps":["Place beans in a large pot and cover with cold water. Soak for at least 4 hours or overnight. Drain and rinse, before you use in the soup.","Chop one of the onions and leave the other one whole. Chop carrots.","Heat oil on a large pot over medium heat. Add the onion and carrots. Cook for 2 minutes. Add beans, water, peppers, head of onion, salt, pepper, summer savory, mint, thyme, Vegeta and tomato puree. Stir, bring to a boil, then reduce to a simmer and cook for 2 hours, or until the beans are tender.","Remove the peppers and whole onion. Mash the onion. Peel peppers and chop. Return to the pot.","Add more salt and pepper, if needed. Garnish with chopped parsley. Serve."],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"87":{"name":"Black Bean soup","photo":"https://www.themealdb.com/images/media/meals/x0mreq1784577446.jpg","url":"https://www.delish.com/cooking/recipe-ideas/a55504/easy-black-bean-soup-recipe/","source":"TheMealDB","originalId":"53546","items":[{"name":"Extra Virgin Olive Oil","q":2.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Red Onions","q":1.0,"u":"medium","section":"Produce","seasoning":false,"prep":""},{"name":"Jalapeno","q":1.0,"u":"","section":"Pantry","seasoning":false,"prep":""},{"name":"Garlic","q":2.0,"u":"cloves minced","section":"Produce","seasoning":false,"prep":""},{"name":"Tomato Puree","q":1.0,"u":"tablespoon","section":"Produce","seasoning":false,"prep":""},{"name":"Kosher Salt","q":1,"u":"","literal":"Pinch","section":"Pantry","seasoning":true,"prep":""},{"name":"Black Pepper","q":1,"u":"","literal":"Pinch","section":"Produce","seasoning":true,"prep":""},{"name":"Ground Cumin","q":1.0,"u":"/2 tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Chilli Powder","q":1.0,"u":"tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Black Beans","q":3.0,"u":"cans","section":"Pantry","seasoning":false,"prep":""},{"name":"Chicken Stock","q":3.0,"u":"Cups","section":"Meat","seasoning":false,"prep":""},{"name":"Bay Leaf","q":1.0,"u":"","section":"Pantry","seasoning":true,"prep":""},{"name":"Sour Cream","q":1,"u":"","literal":"Garnish","section":"Dairy","seasoning":false,"prep":""},{"name":"Avocado","q":1,"u":"","literal":"Garnish","section":"Produce","seasoning":false,"prep":""},{"name":"Cilantro","q":1,"u":"","literal":"Garnish","section":"Produce","seasoning":false,"prep":""},{"name":"Lime","q":1,"u":"","literal":"To serve","section":"Produce","seasoning":false,"prep":""}],"steps":["Step 1","In a large pot over medium heat, heat oil. Add onion and cook until soft and translucent, about 5 minutes. Add jalapeños and garlic and cook until fragrant, about 2 minutes. Add tomato paste, stir to coat vegetables, and cook about a minute more. Season with salt, pepper, cumin, and chili powder and stir to coat.","Step 2","Add black beans and broth. Stir soup, add bay leaf, and bring to a boil. Immediately reduce to a simmer and let simmer until slightly reduced and thickened, 15 to 20 minutes. (If a thinner soup is desired, add more broth as needed.)","Step 3","Remove bay leaf and let cool slightly. Using an immersion blender or food processor, blend soup to desired consistency.","Step 4","Serve with a dollop of sour cream, sliced avocado, and cilantro."],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"88":{"name":"Rosol (Polish Chicken Soup)","photo":"https://www.themealdb.com/images/media/meals/lx1kkj1593349302.jpg","url":"https://polishhousewife.com/rosol-polish-chicken-soup/","source":"TheMealDB","originalId":"53020","items":[{"name":"Chicken Legs","q":4.0,"u":"Chopped","section":"Meat","seasoning":false,"prep":""},{"name":"Onions","q":2.0,"u":"large","section":"Produce","seasoning":false,"prep":""},{"name":"Carrots","q":5.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Leek","q":1.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Celery","q":1.0,"u":"small","section":"Produce","seasoning":false,"prep":""},{"name":"Cabbage","q":1.0,"u":"/4","section":"Produce","seasoning":false,"prep":""},{"name":"Cloves","q":1.0,"u":"whole","section":"Pantry","seasoning":true,"prep":""},{"name":"Allspice","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Bay Leaf","q":2.0,"u":"","section":"Pantry","seasoning":true,"prep":""},{"name":"Parsley","q":4.0,"u":"sprigs","section":"Produce","seasoning":false,"prep":""},{"name":"Dill","q":4.0,"u":"sprigs","section":"Pantry","seasoning":false,"prep":""},{"name":"Pepper","q":1.0,"u":"tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Salt","q":1.0,"u":"tbs","section":"Pantry","seasoning":true,"prep":""}],"steps":["Add chicken to a large Dutch oven or stock pot","Cover with water","Bring to a boil and simmer for 2 to 2 1/2 hours, skimming any impurities off the top to insure a clear broth","If your pot is big enough, add the vegetables and spices for the last hour of the cooking time","My Dutch oven wasn’t big enough to hold everything, just the chicken and other bones filled the pot, so I cooked the meat/bones for the full cooking time, then removed them, and cooked the vegetables and spices separately","Strain everything out of the broth","Bone the chicken, pulling the meat into large chunks","Slice the carrots","Return the chicken and carrots to the broth","Cook noodles according to package instructions if you’re using them","Add noodles to bowl and then top with hot soup"],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"89":{"name":"Bean & Sausage Hotpot","photo":"https://www.themealdb.com/images/media/meals/vxuyrx1511302687.jpg","url":"https://www.bbcgoodfood.com/recipes/339607/bean-and-sausage-hotpot","source":"TheMealDB","originalId":"52848","items":[{"name":"Sausages","q":8.0,"u":"large","section":"Meat","seasoning":false,"prep":""},{"name":"Tomato Sauce","q":1.0,"u":"Jar","section":"Produce","seasoning":false,"prep":""},{"name":"Butter Beans","q":1200.0,"u":"g","section":"Dairy","seasoning":false,"prep":""},{"name":"Black Treacle","q":1.0,"u":"tbls","section":"Pantry","seasoning":false,"prep":""},{"name":"English Mustard","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""}],"steps":["In a large casserole, fry the sausages until brown all over – about 10 mins.","Add the tomato sauce, stirring well, then stir in the beans, treacle or sugar and mustard.","Bring to the simmer, cover and cook for 30 mins.","Great served with crusty bread or rice."],"cat":"Rice & Bowls","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"90":{"name":"Nom Banh Chok – Cambodian Noodle Soup","photo":"https://www.themealdb.com/images/media/meals/6g9gif1782688663.jpg","url":"https://recipes-for-life.com/cambodian-recipes/","source":"TheMealDB","originalId":"53497","items":[{"name":"Water","q":8.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Chicken Thighs","q":1.0,"u":"lb","section":"Meat","seasoning":false,"prep":""},{"name":"Garlic","q":4.0,"u":"Cloves Crushed","section":"Produce","seasoning":false,"prep":""},{"name":"Vegetable Oil","q":2.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Fish Sauce","q":1.0,"u":"tablespoon","section":"Meat","seasoning":false,"prep":""},{"name":"Salt","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Sugar","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Rice Noodles","q":8.0,"u":"oz","section":"Pantry","seasoning":false,"prep":""},{"name":"Bean Sprouts","q":2.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Mint","q":1.0,"u":"cup","section":"Pantry","seasoning":false,"prep":""},{"name":"Lime","q":1.0,"u":"","section":"Produce","seasoning":false,"prep":""},{"name":"Red Chilli","q":1.0,"u":"","section":"Produce","seasoning":false,"prep":""}],"steps":["1. Heat the vegetable oil in a large pot over medium heat until it shimmers, about 2 minutes.","2. Add the minced garlic and sauté until fragrant and lightly golden, about 1 minute, stirring constantly to prevent burning.","3. Add the chicken pieces and cook until they turn opaque on all sides, about 5 minutes, stirring occasionally.","4. Pour in the 8 cups of water and bring to a boil over high heat, which should take about 8 minutes.","5. Reduce the heat to low, stir in the fish sauce, salt, and sugar, and simmer uncovered for 20 minutes to develop the flavors.","6. While the broth simmers, cook the rice noodles according to package instructions until al dente, then drain and rinse under cold water to stop the cooking.","7. Divide the cooked noodles evenly among four bowls.","8. Ladle the hot broth and chicken over the noodles in each bowl.","9. Top each bowl with bean sprouts, chopped mint leaves, and optional red chili slices.","10. Serve immediately with lime wedges on the side for squeezing over the soup."],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"91":{"name":"Antiguan Breakfast (Chop Up and ‘Saltfish’)","photo":"https://www.themealdb.com/images/media/meals/jvjnoh1780086318.jpg","url":"https://www.atastefortravel.ca/24626-antigua-chop-up/#recipe","source":"TheMealDB","originalId":"53430","items":[{"name":"Egg Plants","q":4.0,"u":"","section":"Dairy","seasoning":false,"prep":""},{"name":"Callaloo","q":8.0,"u":"oz","section":"Pantry","seasoning":false,"prep":""},{"name":"Pumpkin","q":1.0,"u":"lb","section":"Pantry","seasoning":false,"prep":""},{"name":"Garlic","q":3.0,"u":"cloves Chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Onion","q":1.0,"u":"Diced","section":"Produce","seasoning":false,"prep":""},{"name":"Butter","q":2.0,"u":"oz","section":"Dairy","seasoning":false,"prep":""},{"name":"Salt","q":1.0,"u":"/2 tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Black Pepper","q":1.0,"u":"/4 tsp","section":"Produce","seasoning":true,"prep":""}],"steps":["Peel and chop eggplant and pumpkin into medium-sized pieces.","Heat butter and add onions and garlic in a medium sized pot set to medium to high heat. Sauté for 2 minutes until softened but not browned.","Add pumpkin and eggplant. Sauté for an additional two to three minutes.","Add water just to cover the vegetables. Bring to a boil, reduce heat to a simmer and cook until the vegetables are soft.","Add the chopped spinach, stir and cook for an additional 3 minutes.","Pour the vegetable mixture into a colander and let drain.","After vegetable mixture has been drained return it to the pot and mash vigorously with a potato masher or a thick whisk.","Add salt and pepper. Adjust seasoning to taste."],"cat":"Quick & Breakfast","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"92":{"name":"Dutch poffertjes (mini pancakes)","photo":"https://www.themealdb.com/images/media/meals/oaqz9f1766593912.jpg","url":"https://insimoneskitchen.com/old-dutch-poffertjes/#recipe","source":"TheMealDB","originalId":"53379","items":[{"name":"Flour","q":125.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Buckwheat Flour","q":125.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Eggs","q":2.0,"u":"","section":"Dairy","seasoning":false,"prep":""},{"name":"Butter","q":1.0,"u":"knob","section":"Dairy","seasoning":false,"prep":""},{"name":"Milk","q":300.0,"u":"ml","section":"Dairy","seasoning":false,"prep":""},{"name":"Yeast","q":10.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"vanilla sugar","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Butter","q":1,"u":"","literal":"To serve","section":"Dairy","seasoning":false,"prep":""},{"name":"Icing Sugar","q":1,"u":"","literal":"To serve","section":"Pantry","seasoning":true,"prep":""}],"steps":["Mix the dry yeast with some of the luke warm milk en stir until dissolved.","Place buckwheat and the flour together in a bowl and make a small circle in the middle. Add the yeast mixture into it. Add the milk and stir until you have a smooth batter.","Add the eggs, salt and vanille sugar and stir through. Leave to stand and rise for about 45 minutes.","Heat the poffertjespan and add a bit of butter into each hole. Fill halfway with batter and first bake one side until you can see the top dry out a little. Turn the poffertjes around with a small fork and bake the other side until cooked and golden brown.","Serve the poffertjes with butter and icing sugar"],"cat":"Quick & Breakfast","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"93":{"name":"Chinese Tomato Egg Stir Fry","photo":"https://www.themealdb.com/images/media/meals/rwvw8q1765660071.jpg","url":"https://www.simplyrecipes.com/chinese-tomato-egg-recipe-7562056","source":"TheMealDB","originalId":"53372","items":[{"name":"Plum Tomatoes","q":1.0,"u":"lb","section":"Produce","seasoning":false,"prep":""},{"name":"Vegetable Oil","q":1.0,"u":"tablespoon","section":"Pantry","seasoning":true,"prep":""},{"name":"Eggs","q":5.0,"u":"Large","section":"Dairy","seasoning":false,"prep":""},{"name":"Sesame Seed Oil","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Chicken Bouillon Powder","q":2.0,"u":"tsp","section":"Meat","seasoning":false,"prep":""},{"name":"Sugar","q":2.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Pepper","q":1.0,"u":"/2 tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Salt","q":1.0,"u":"/4 tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Spring Onions","q":1.0,"u":"","section":"Produce","seasoning":false,"prep":""},{"name":"Jasmine Rice","q":2.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""}],"steps":["You can use chicken broth in place of the chicken bouillon powder. Add 1/4 cup of broth followed by 2 teaspoons of cornstarch dissolved in 1 tablespoPrepare the tomatoes:","Slice the tomatoes in half. Remove the tough stem from each half that connects to the vine. Cut each half into equal thirds (you’ll get 6 slices from each tomato).","Make the soft scrambled eggs:","In a cold, 8 to 10-inch nonstick skillet, add the vegetable oil and beaten eggs. Turn the heat to medium. Once a thin layer of eggs is just beginning to cook on the bottom, push the eggs in one direction to create layers of scrambled eggs.","Cook, gently stirring the whole time, until the scramble eggs are mostly set but still slightly wet and shiny, 2 to 5 minutes. Remove the eggs to a plate and, if needed, wipe out the pan.","Stir-fry the tomatoes and seasonings:","Add the sesame oil to the pan followed by the tomatoes and stir-fry over medium heat until the tomatoes are softened but not mushy, about 3 minutes. Add the chicken bouillon powder, sugar, and white pepper. Toss until combined and the sugar and bouillon have dissolved, about 1 minute.","Add eggs, stir-fry, and garnish:","Add the eggs back to the pan with the tomatoes. Stir-fry for about 2 minutes to heat through and combine. Taste, adding salt only if needed. Sprinkle with the green onions and serve with steamed rice.on of water, plus salt to taste."],"cat":"Vegetarian","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"94":{"name":"Fruit and Cream Cheese Breakfast Pastries","photo":"https://www.themealdb.com/images/media/meals/1543774956.jpg","url":"https://www.themealdb.com/meal/52957","source":"TheMealDB","originalId":"52957","items":[{"name":"Cream Cheese","q":1.25,"u":"oz","section":"Dairy","seasoning":false,"prep":""},{"name":"Sugar","q":1.25,"u":"cup","section":"Pantry","seasoning":true,"prep":""},{"name":"Vanilla Extract","q":1.0,"u":"teaspoon","section":"Pantry","seasoning":false,"prep":""},{"name":"Flour","q":1,"u":"","literal":"quantity not specified","section":"Pantry","seasoning":false,"prep":""},{"name":"Puff Pastry","q":2.0,"u":"","section":"Pantry","seasoning":false,"prep":""},{"name":"Strawberries","q":1,"u":"","literal":"quantity not specified","section":"Pantry","seasoning":false,"prep":""},{"name":"Raspberries","q":1,"u":"","literal":"quantity not specified","section":"Pantry","seasoning":false,"prep":""},{"name":"Blackberries","q":1,"u":"","literal":"quantity not specified","section":"Pantry","seasoning":false,"prep":""}],"steps":["Preheat oven to 400ºF (200ºC), and prepare two cookie sheets with parchment paper. In a bowl, mix cream cheese, sugar, and vanilla until fully combined. Lightly flour the surface and roll out puff pastry on top to flatten. Cut each sheet of puff pastry into 9 equal squares. On the top right and bottom left of the pastry, cut an L shape approximately ½ inch (1 cm) from the edge.","NOTE: This L shape should reach all the way down and across the square, however both L shapes should not meet at the ends. Your pastry should look like a picture frame with two corners still intact.","Take the upper right corner and fold down towards the inner bottom corner. You will now have a diamond shape.","Place 1 to 2 teaspoons of the cream cheese filling in the middle, then place berries on top.","Repeat with the remaining pastry squares and place them onto the parchment covered baking sheet.","Bake for 15-20 minutes or until pastry is golden brown and puffed.","Enjoy!"],"cat":"Quick & Breakfast","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"95":{"name":"Chorizo & soft-boiled egg salad","photo":"https://www.themealdb.com/images/media/meals/v8eaed1763257313.jpg","url":"https://www.bbcgoodfood.com/recipes/chorizo-soft-boiled-egg-salad","source":"TheMealDB","originalId":"53157","items":[{"name":"Baby New Potatoes","q":500.0,"u":"g","section":"Produce","seasoning":false,"prep":""},{"name":"Egg","q":4.0,"u":"","section":"Dairy","seasoning":false,"prep":""},{"name":"Green Beans","q":225.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Chorizo","q":225.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Garlic Clove","q":1.0,"u":"sliced","section":"Produce","seasoning":true,"prep":""},{"name":"Sherry vinegar","q":2.0,"u":"tbsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Parsley","q":2.0,"u":"tbsp chopped","section":"Produce","seasoning":false,"prep":""}],"steps":["step 1","Cook the potatoes in a large pan of boiling salted water for 12 mins, adding the eggs after 6 mins, and the beans for the final 2 mins. Drain everything and cool the eggs under cold running water.","step 2","Meanwhile fry chorizo slices for 1-2 mins, until beginning to crisp. Remove from the pan with a slotted spoon and set aside, leaving the oil from the chorizo in the pan. Add the garlic to the pan and cook gently for 1 min.","step 3","Remove the pan from the heat, stir in the vinegar and parsley, then toss with the potatoes, beans, chorizo and seasoning. Shell the eggs, cut into quarters and add to the salad."],"cat":"Rice & Bowls","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"96":{"name":"Chorba Hamra bel Frik (Algerian Lamb, Tomato, and Freekeh Soup)","photo":"https://www.themealdb.com/images/media/meals/p9tebp1764118792.jpg","url":"https://www.allrecipes.com/recipe/264552/chorba-hamra-bel-frik-algerian-lamb-tomato-and-freekeh-soup/","source":"TheMealDB","originalId":"53289","items":[{"name":"Freekeh","q":1.0,"u":"cup","section":"Pantry","seasoning":false,"prep":""},{"name":"Lamb","q":12.0,"u":"ounces","section":"Meat","seasoning":false,"prep":""},{"name":"Onion","q":1.0,"u":"finely chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Black Pepper","q":1.0,"u":"tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Paprika","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Ground Cinnamon","q":1.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Salt","q":1,"u":"","literal":"To taste","section":"Pantry","seasoning":true,"prep":""},{"name":"Vegetable Oil","q":3.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Cilantro","q":1.0,"u":"bunch","section":"Produce","seasoning":false,"prep":""},{"name":"Mint","q":1.0,"u":"bunch","section":"Pantry","seasoning":false,"prep":""},{"name":"Celery","q":1.0,"u":"","section":"Produce","seasoning":false,"prep":""},{"name":"Chickpeas","q":14.0,"u":"oz jar","section":"Pantry","seasoning":false,"prep":""},{"name":"Water","q":4.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Zucchini","q":1.0,"u":"Diced","section":"Produce","seasoning":false,"prep":""},{"name":"Carrots","q":1.0,"u":"Diced","section":"Produce","seasoning":false,"prep":""},{"name":"Tomato Puree","q":1.0,"u":"tablespoon","section":"Produce","seasoning":false,"prep":""},{"name":"Tomato","q":3.0,"u":"Medium","section":"Produce","seasoning":false,"prep":""},{"name":"Potatoes","q":1.0,"u":"Diced","section":"Produce","seasoning":false,"prep":""}],"steps":["Place freekeh in a small bowl and cover with cold water. Set aside.","Combine lamb, onion, black pepper, paprika, cinnamon, and salt in a pot. Stir in oil, 1/2 the cilantro, 1/2 the mint, and celery stalk until combined. Simmer over low heat for 15 minutes. Stir in chickpeas; pour in just enough water to cover, and return to a simmer. Stir in zucchini, carrot, and tomato paste.","Set a steamer over the pot; add tomatoes. Cover and steam tomatoes until soft, about 5 minutes. Crush tomatoes using a wooden spoon, so pulp drips into soup. Remove the steamer and discard leftover tomato peels.","Add potato to soup and just enough water to cover. Simmer until potato is soft, about 10 minutes.","Drain freekeh and add to soup. Simmer until soft, about 15 minutes. Remove celery stalk and discard. Sprinkle soup with remaining 1/2 cilantro and remaining 1/2 mint before serving."],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"97":{"name":"Creamy Corn Soup Recipe","photo":"https://www.themealdb.com/images/media/meals/yf5eyw1783804464.jpg","url":"https://www.mycolombianrecipes.com/corn-soup-crema-de-mazorca/#recipe","source":"TheMealDB","originalId":"53532","items":[{"name":"Corn On The Cob","q":4.0,"u":"","section":"Pantry","seasoning":false,"prep":""},{"name":"Water","q":6.0,"u":"cups","section":"Pantry","seasoning":false,"prep":""},{"name":"Chicken Stock Cube","q":2.0,"u":"","section":"Meat","seasoning":false,"prep":""},{"name":"Garlic","q":2.0,"u":"cloves chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Salt","q":1.0,"u":"/2 tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Pepper","q":1.0,"u":"/2 tsp","section":"Produce","seasoning":true,"prep":""},{"name":"Cilantro","q":2.0,"u":"tablespoons","section":"Produce","seasoning":false,"prep":""},{"name":"Potatoes","q":1.0,"u":"/2 cup","section":"Produce","seasoning":false,"prep":""},{"name":"Scallions","q":1.0,"u":"/2 cup","section":"Pantry","seasoning":false,"prep":""},{"name":"Heavy Cream","q":1.0,"u":"cup","section":"Dairy","seasoning":false,"prep":""}],"steps":["Place the corn, water, chicken or vegetable bouillon, garlic, salt, pepper, cilantro, potatoes and scallions in a large pot and bring to a boil. Reduce heat to medium low and simmer for approximately 4 minutes or until the corn is tender.","Remove from the heat. Puruée the soup in a blender and return to the pot, add the cream and heat over medium heat for 15 minutes, stirring occasionally.","Pour into bowls, garnish with cilantro and potato sticks.","Notes","*Fresh corn or frozen corn will work for this soup recipe. I usually use fresh corn, but I use organic corn kernels in the winter to make this soup.","*To store: Place cooled corn soup in an airtight container and store in the fridge for up to 3 days."],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"98":{"name":"Bahia-style Moqueca prawn stew","photo":"https://www.themealdb.com/images/media/meals/e2kcut1782591669.jpg","url":"https://www.bbcgoodfood.com/recipes/bahia-style-moqueca-prawn-stew","source":"TheMealDB","originalId":"53481","items":[{"name":"Raw King Prawns","q":450.0,"u":"g","section":"Meat","seasoning":false,"prep":""},{"name":"Lime juice","q":75.0,"u":"ml","section":"Produce","seasoning":false,"prep":""},{"name":"Garlic","q":3.0,"u":"cloves Chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Coconut Oil","q":3.0,"u":"tablespoons","section":"Pantry","seasoning":true,"prep":""},{"name":"Spring Onions","q":4.0,"u":"Chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Onion","q":1.0,"u":"","section":"Produce","seasoning":false,"prep":""},{"name":"Red Pepper","q":1.0,"u":"chopped","section":"Produce","seasoning":true,"prep":""},{"name":"Chilli Flakes","q":1.0,"u":"tsp","section":"Produce","seasoning":false,"prep":""},{"name":"Paprika","q":2.0,"u":"tsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Plum Tomatoes","q":3.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Coconut Milk","q":400.0,"u":"ml","section":"Dairy","seasoning":false,"prep":""},{"name":"Coriander","q":2.0,"u":"tbs chopped","section":"Pantry","seasoning":false,"prep":""},{"name":"Rice","q":1,"u":"","literal":"To serve","section":"Pantry","seasoning":false,"prep":""}],"steps":["step 1","Place the prawns in a bowl with 2 tbsp of the lime juice, 1 tsp of salt and 1 tbsp of the chopped garlic. Chill for 1 hr.","step 2","Heat the coconut oil in a large saucepan. Add the spring onion and onion and fry for 5 mins, then add the red pepper, chilli flakes, paprika and remaining garlic.","step 3","Pour in the tomatoes, coconut milk and a little salt. Bring to a simmer and let reduce for 10 mins. Add the prawns, all the marinade and remaining lime juice. Gently simmer until the prawns turn white, about 3 mins. Serve with the fresh coriander and rice."],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline. The original placeholder has been replaced with a different real published recipe; the displayed name is the publisher's exact dish name."},"99":{"name":"Creamy Tomato Soup","photo":"https://www.themealdb.com/images/media/meals/stpuws1511191310.jpg","url":"https://www.bbcgoodfood.com/recipes/2604646/creamy-tomato-soup","source":"TheMealDB","originalId":"52841","items":[{"name":"Olive Oil","q":3.0,"u":"tbsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Onions","q":2.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Celery","q":2.0,"u":"sticks","section":"Produce","seasoning":false,"prep":""},{"name":"Carrots","q":300.0,"u":"g","section":"Produce","seasoning":false,"prep":""},{"name":"Potatoes","q":500.0,"u":"g","section":"Produce","seasoning":false,"prep":""},{"name":"Bay Leaf","q":4.0,"u":"","section":"Pantry","seasoning":true,"prep":""},{"name":"Tomato Puree","q":5.0,"u":"tblsp","section":"Produce","seasoning":false,"prep":""},{"name":"Sugar","q":2.0,"u":"tblsp","section":"Pantry","seasoning":true,"prep":""},{"name":"White Vinegar","q":2.0,"u":"tblsp","section":"Pantry","seasoning":true,"prep":""},{"name":"Chopped Tomatoes","q":1.5,"u":"kg","section":"Produce","seasoning":false,"prep":""},{"name":"Passata","q":500.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Vegetable Stock Cube","q":3.0,"u":"","section":"Pantry","seasoning":false,"prep":""},{"name":"Whole Milk","q":400.0,"u":"ml","section":"Dairy","seasoning":false,"prep":""}],"steps":["Put the oil, onions, celery, carrots, potatoes and bay leaves in a big casserole dish, or two saucepans. Fry gently until the onions are softened – about 10-15 mins. Fill the kettle and boil it.","Stir in the tomato purée, sugar, vinegar, chopped tomatoes and passata, then crumble in the stock cubes. Add 1 litre boiling water and bring to a simmer. Cover and simmer for 15 mins until the potato is tender, then remove the bay leaves. Purée with a stick blender (or ladle into a blender in batches) until very smooth. Season to taste and add a pinch more sugar if it needs it. The soup can now be cooled and chilled for up to 2 days, or frozen for up to 3 months.","To serve, reheat the soup, stirring in the milk – try not to let it boil. Serve in small bowls with cheesy sausage rolls."],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."},"100":{"name":"Black bean & meat stew - feijoada","photo":"https://www.themealdb.com/images/media/meals/xrxz7h1782592711.jpg","url":"https://www.bbcgoodfood.com/recipes/black-bean-meat-stew-feijoada","source":"TheMealDB","originalId":"53482","items":[{"name":"Black Beans","q":250.0,"u":"g","section":"Pantry","seasoning":false,"prep":""},{"name":"Bacon","q":100.0,"u":"g","section":"Meat","seasoning":false,"prep":""},{"name":"Pork Back Ribs","q":500.0,"u":"g","section":"Meat","seasoning":false,"prep":""},{"name":"Chorizo","q":3.0,"u":"","section":"Pantry","seasoning":false,"prep":""},{"name":"Pork Shoulder","q":500.0,"u":"g","section":"Meat","seasoning":false,"prep":""},{"name":"Onion","q":3.0,"u":"chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Garlic","q":4.0,"u":"Cloves Chopped","section":"Produce","seasoning":false,"prep":""},{"name":"Chilli Flakes","q":1,"u":"","literal":"Pinch","section":"Produce","seasoning":false,"prep":""},{"name":"Oil","q":1,"u":"","literal":"Drizzle","section":"Pantry","seasoning":true,"prep":""},{"name":"Bay Leaf","q":2.0,"u":"","section":"Pantry","seasoning":true,"prep":""}],"steps":["step 1","Heat a large heavy-based saucepan with a fitted lid, add the bacon and fry until crisp. Remove and keep the oil in the pan. In batches sear the ribs, sausages and pork shoulder. Season each batch with salt and pepper.","step 2","Remove the meat and set aside. Add the onion, garlic and chilli to the pan. Pour in a little olive oil if it needs more. Season with salt and pepper and fry for 8 mins or until soft.","step 3","Add the meat, bay leaves, white wine vinegar and drained beans. Cover with just enough water to cover, about 650ml. Bring to a boil and reduce the heat to a low simmer. Cover and cook for 2 hrs, or until the beans are soft and the meat is tender. If there is too much liquid in the pot take the lid off in the last hr. You can also use a slow cooker on the short method (4 hr) or make a quick version using a pressure cooker in batches for 30 mins each. Another method is to cook it in the oven for 3-4 hrs at 160C/140C fan/gas 3.","step 4","Serve with rice, a sprinkle of parsley or coriander, hot pepper sauce and orange slices."],"cat":"Soups","time":null,"servings":4,"sourceHasNoYield":true,"note":"The recipe name, ingredient amounts, instructions and photo all come from one published source. The source does not specify servings; four portions is used only as an estimated grocery-list baseline."}});
